export const repairGroup = async (vm: Vm, pr: RenovatePr, charter: Charter): Promise<RepairResult> => {
  const breaking: Bump[] = [];
  for (const bump of pr.bumps) {                       // 1. each bump alone, on the base commit
    await vm.checkout(pr.baseSha);
    await vm.applyBump(bump);
    if (!(await vm.run(charter.verify_cmd))) breaking.push(bump);
  }
  const fixCommits: string[] = [];
  for (const bump of breaking) {                       // 2. one fix session per breaking package
    await vm.checkout(pr.baseSha);
    await vm.applyBump(bump);
    const result = await vm.session({ task: "upgrade-dependency", package: bump.package, to: bump.newVersion,
                                      context: [bump.changelogUrl, await vm.usages(bump.package)] });
    if (!result.green) return RepairResult.handOff(bump, result.notes);
    fixCommits.push(...result.commits);
  }
  await vm.checkout(pr.headSha);                       // 3. all fixes together, on the Renovate branch
  await vm.cherryPick(fixCommits);
  if (!(await vm.run([charter.verify_cmd, ...charter.flow_checks]))) {
    return RepairResult.handOff(undefined, "the fixes pass one by one but not together");
  }
  return RepairResult.push({ branch: pr.headBranch });
};

